<?php
namespace Tests\Feature;
use App\Actions\Culinary\CreateCulinaryReservation;use App\Actions\Culinary\DecideCulinaryReservation;use App\Models\CatalogEntity;use App\Models\CulinaryTableSlot;use App\Models\Mitra;use App\Models\ServiceType;use App\Models\User;use Database\Seeders\FoundationReferenceSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Spatie\Permission\PermissionRegistrar;use Tests\TestCase;
class CulinaryModuleTest extends TestCase
{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(FoundationReferenceSeeder::class);setPermissionsTeamId(null);}public function test_canonical_culinary_relations_and_public_visibility():void{[$owner,$mitra,$entity]=$this->venue();$this->assertSame($entity->id,$entity->culinary->catalog_entity_id);$this->get(route('culinary.show',$entity->slug))->assertNotFound();$entity->update(['status'=>'published','published_at'=>now()]);$this->get(route('culinary.show',$entity->slug))->assertOk()->assertSee($entity->name);}
public function test_reservation_capacity_prevents_overbooking_and_records_audit():void{[$owner,$mitra,$entity]=$this->venue();$slot=CulinaryTableSlot::create(['culinary_venue_id'=>$entity->culinary->id,'service_date'=>now()->addDay(),'starts_at'=>'18:00','ends_at'=>'20:00','capacity_tables'=>2,'capacity_guests'=>4,'status'=>'available']);$consumer=User::factory()->create();$action=app(CreateCulinaryReservation::class);$first=$action->execute($slot,$consumer,['party_size'=>3,'contact_name'=>'Budi','contact_phone'=>'081234567890']);$this->expectException(ValidationException::class);try{$action->execute($slot,User::factory()->create(),['party_size'=>2,'contact_name'=>'Siti','contact_phone'=>'081234567891']);}finally{$this->assertDatabaseHas('culinary_reservations',['id'=>$first->id,'status'=>'requested']);$this->assertDatabaseHas('audit_logs',['event'=>'culinary.reservation_requested']);}}
public function test_mitra_decision_is_tenant_protected_and_notified():void{[$owner,$mitra,$entity]=$this->venue();$slot=CulinaryTableSlot::create(['culinary_venue_id'=>$entity->culinary->id,'service_date'=>now()->addDay(),'starts_at'=>'18:00','ends_at'=>'20:00','capacity_tables'=>2,'capacity_guests'=>4]);$consumer=User::factory()->create();$reservation=app(CreateCulinaryReservation::class)->execute($slot,$consumer,['party_size'=>2,'contact_name'=>'Budi','contact_phone'=>'081234567890']);app(DecideCulinaryReservation::class)->execute($reservation,'confirm',$owner);$this->assertSame('confirmed',$reservation->fresh()->status->value);$this->assertDatabaseHas('notifications',['user_id'=>$consumer->id]);[$other,$otherMitra]=$this->tenant('culinary');$this->actingAs($other)->withSession(['active_mitra_id'=>$otherMitra->id])->patch(route('mitra.culinary.reservations.decide',[$entity,$reservation]),['decision'=>'reject','reason'=>'x'])->assertForbidden();}
private function venue():array{[$user,$mitra,$service]=$this->tenant('culinary');$entity=CatalogEntity::create(['mitra_id'=>$mitra->id,'service_type_id'=>$service->id,'name'=>'Dapur Tegal','slug'=>'dapur-tegal-'.str()->lower(str()->random(5)),'description'=>'Kuliner lokal dengan menu khas yang lengkap.','address'=>'Tegal','status'=>'draft']);$entity->culinary()->create(['venue_type'=>'restaurant','accepts_reservations'=>true]);return[$user,$mitra,$entity->fresh('culinary')];}private function tenant(string $code):array{$user=User::factory()->create();$mitra=Mitra::factory()->for($user,'owner')->create(['status'=>'active','approved_at'=>now()]);$mitra->members()->create(['user_id'=>$user->id,'status'=>'active','joined_at'=>now()]);setPermissionsTeamId($mitra->id);$user->assignRole('mitra-owner');app(PermissionRegistrar::class)->forgetCachedPermissions();setPermissionsTeamId(null);$service=ServiceType::where('code',$code)->firstOrFail();$mitra->features()->create(['service_type_id'=>$service->id,'status'=>'enabled','enabled_at'=>now()]);return[$user,$mitra,$service];}}
